    feedsHomeDesc: 'خلاصة مختلطة من النصوص والصور والمقالات والفيديو والصوت والمشاركات المباشرة. يتم تضمين الإعجابات والتعليقات وإعادة النشر والاقتباسات والإشارات المرجعية والإكراميات الرمزية في كل بطاقة، ويمكن إنشاء بوابات للمشاركات أو الدفع مقابل المشاهدة أو ضبطها على watch2earn. حتى لا يتمكن أحد من إغراقها، تحمل خلاصة المنزل عددًا محدودًا من منشورات كل مؤلف يوميًا: واحدة بدون شارة وواحدة أخرى لكل فئة شارة، تصل إلى أربعة عشر في Megalodon. كل شيء لا يزال يظهر على الملف الشخصي للمؤلف وفي النوع التالي.',
    feedsMature: 'محتوى البالغين:',
    feedsMatureDesc: 'يضع المبدعون علامة محتوى بالغين على المنشور أثناء إنشائه. وتبقى هذه المنشورات خارج التغذية الرئيسية العامة وخارج البحث، لكنها تظل ظاهرة بالكامل في ملف المبدع ولمن يتابعونه. أما المشاهدون الذين يريدونها في كل مكان فيفعّلون خيار إظهار محتوى البالغين في الإعدادات.',
