    feedsReactions: 'التفاعلات:',
    feedsReactionsDesc: 'عشرة ردود أفعال تجلس خلف زر الإعجاب: مثل الحب والاحترام والساخنة و 100 ولول والحزن والبكاء والتغوط والكراهية. كل واحد باستثناء عدم الإعجاب يتم احتسابه في إجمالي المنشور. انقر نقرًا مزدوجًا فوق منشور لإعجابه، وانقر نقرًا ثلاثيًا لإعجابه، واضغط مع الاستمرار على الزر لفتح الدرج، مما يدل على من تفاعل وماذا. الرمز الرئيسي على البطاقة هو أي رد فعل جذبه المنشور أكثر. يتم ترجيح التفاعل بواسطة شارة المفاعل، لذا فإن من كان له رد فعل مهم وكذلك عدد من فعلوا ذلك. يحرك الوضع الأيسر في الإعدادات زر الإعجاب إلى يسار الشريط.',
