    moreB4Desc: 'تصنيفات المبدعين الذين يوزعون دخل الإعلانات، وأفضل 100 حساب على المنصة.',
    moreB5Desc: 'مستودع للمبدعين للعثور عليهم والتابع لهم، بالإضافة إلى قائمة الأعضاء الجدد لكل من وصل حديثًا.',
