    notificationsB6: 'وسامك:',
    notificationsB6Desc: 'يرمز البuzzer لك عندما يرتفع أو ينخفض وسامك، وكل إشعار يظهر وسام الشخص الخلفي.',
    tocKids: 'وضع Kids Mode',
    kidsTitle: 'وضع Kids Mode',
    packsB1: 'صنع حزمة:',
    packsB2: 'شاركها:',
    tocCinema: 'سينما',
    cinemaTitle: 'سينما',
    themesTitle: 'الموضوعات والأداء',
    themesDesc: 'تُرسل DeHub ستة عشر خيارًا لتصميم الشاشة، وليس فقط التبديل بين اللون الفاتح والظل: نظام، نظام فاتح، ممتد، ممتد فاتح، كواسميك، مينيمال، مينيمال فاتح، كوسميك، هزي، سوارم، لافا لامب، شتاء، حرب، أوساكا، جنجل، جزيرة، HACKER، وحش. كل واحد هو جلد كامل — لوحة ألوان خاصة، وchrome، ورموز، وله بعضها خلفية متحركة حية يتم إنشاءها على GPU. نظام هو ممتد تمامًا، مع مشاركات من الشكل الكامل التي يتم تقسيمها بخطوط رقيقة بدلاً من boxes، ونظام فاتح هو نفس المخطط في الحبر الأسود على الأبيض. جزيرة هي بحيرة مع ماء متماثل يتبع ساعةك المحلية من الساعة الذهبية إلى الليل، وHACKER هو مطر أخضر سريع مع التطبيق المثبت في monospace، وحش هو footage المكتشف على قرص فيديو مكسور. اختر واحدًا في الإعدادات → الأداء، حيث يظهر كل واحد نموذجًا، ويمكنك تعيين لون ملمس خاص مع بعضها، وجنجل لديه مفتاحين للنهار والليل.',
    appsTitle: 'الحصول على التطبيق',
    appsB1: 'الويب:',
    appsB2: 'أندرويد:',
    appsB3: 'حساب واحد لكل شي:',
    studioTitle: 'استوديو ومحرر المبدعين (Creator Studio & Editor)',
    studioDesc: 'استوديو المبدعين هو المكان اللي بتصنع فيه المحتوى مش بس بتنشره. بيعمل صور، فيديوهات، موسيقى، أصوات، ونماذج 3D من خلال "برومبت" (أمر نصي)، وبيخلي قائمة الريندر (render queue) شغالة بالخلفية وأنت بتكمل تصفح بالتطبيق، وبعدين بيسلم النتائج لمحرر بيشبه "كانفا" عشان ترتب، تقص، وتضيف تعليقات. وفيه مكتبة مجانية للمواد الجاهزة (stock assets) جنبه، يعني بتقدر تبني المنشور من الألف للياء بدون ما تحتاج أدوات خارجية أو اشتراك بأي شي تاني.',
    studioB2: 'تعديل:',
    studioB3: 'قائمة الانتظار والمكتبة:',
    studioB4: 'رصيد أو خطة:',
    studioB4Desc: 'ادفع مقابل كل شغلة بتعملها بـ DeHub tokens، والسعر بيطلعلك قبل ما تبدأ. المستخدمين اللي شغلهم تقيل بيقدروا يشتركوا بخطة Creator أو Ultra أو Team أو Scale عشان يحصلوا على رصيد شهري من التوكنز - الخطط موجودة بـ dehub.io/pricing.',
    studioB5: 'مسار المبدع (Creator Flow) والإعدادات المسبقة:',
    studioB5Desc: 'مسار المبدع بـ dehub.io/creator/flow بيربط خطوات البرومبت، المراجع، والمولد على لوحة عمل واحدة وبيحسب سعر العملية كلها كدفعة واحدة. فيه مئات الإعدادات المسبقة (presets) اللي بتقدر تبحث عنها، بتغطي تصوير المنتجات، محتوى المستخدمين (UGC)، تنسيقات الإعلانات، ستايلات الرسم، تأثيرات الفيديوهات الفايرل، قوالب الحركة، وقوالب الشخصيات، وكل إعداد مسبق منشور بالاستوديو بتقدر تلاقيه بنفس البحث.',
    studioDesc3: 'المحرر صار بيشتغل كأنه استوديو لحاله. المشاريع بتنحفظ على الكلاود مع سجل للنسخ (version history) وبتتزامن بسلاسة بين أجهزتك، وبتقدر تشارك مقطع للمراجعة: المراجعين بيقدروا يتركوا تعليقات مثبتة على لحظة معينة بالفيديو، والمحررين اللي بتدعيهم بيقدروا يشتغلوا على نفس المشروع بنفس الوقت بدون ما يخربوا شغل بعض.',
    studioB6: 'تعديل ذكي:',
    studioB6Desc: 'المحرر بيلاقي اللقطات المميزة من الكلام أو اللي طالع على الشاشة، بيكتشف تغييرات المشاهد، بيحدد الإيقاعات (beats) بالموسيقى وبيرتب القصات عليها، بيشيل الخلفيات، وبيقدر يركب "قصة أولية" (first cut) من الميديا اللي عندك لما توصفله شو بدك.',
    studioB7: 'صوت وتعليقات:',
    studioB7Desc: 'وزن مستوى الصوت، تنقية الأصوات، توليد موسيقى تصويرية أو مؤثرات صوتية، استيراد ملفات الترجمة، ضبط التعليقات داخل الإطار، وترجمة شريط التعليقات كامل للغة تانية مع خيار التراجع (Undo).',
    studioB8: 'تسجيل وتصدير:',
    studioB8Desc: 'سجل من الكاميرا، الميكروفون، أو الشاشة مباشرة على التايم لاين، وبعدين صدر الفيديو، أو GIF متحرك، أو كل صفحة من التصميم، أو كل مقطع كملف لحاله، وشارك النتيجة من خلال قائمة المشاركة بجهازك.',
    studioB9: 'مابوروشي',
    studioB9Desc: 'Maboroshi موجود جوا "المبدع" عشان استبدال الفيديو وشغل الشخصيات، مع 180 إعداد مسبق، وخيارات الدفع الخاصة بـ Creator، وخيار ريندر بتكلفة أقل.',
    tocConverter: 'محول (Converter)',
    converterTitle: 'المحول: جيب محتواك',
    converterDesc: 'المحول بـ dehub.io/converter بينشر المحتوى اللي عندك بمكان تاني كمنشورات على بروفايلك بـ DeHub. حط الرابط، شوف كيف رح يطلع المنشور، وحط قد ما بدك بقائمة الانتظار - بيشتغلوا واحد ورا التاني بالخلفية وبيظهروا بشبكة (grid) بتقدر ترجعلها وتجرب مرة تانية.',
    converterB1: 'واحد وعشرين مصدر:',
