    arcadeTitle: 'الأركيد (Arcade)',
    arcadeDesc: 'الأركيد هو رف فيه ألعاب بتشتغل جوا DeHub بتاب المتصفح. ما في شي يتحمل، ما في شي ينشرى، وما في حساب منفصل: افتح وحدة والعب. ست ألعاب متوفرة اليوم: King\'s Gambit، لعبة شطرنج سينمائية 3D مع نظام تصنيف Elo أونلاين؛ Claude of Duty، لعبة تصويب بتولد كل الـ mesh والـ texture والصوت على جهازك وأنت عم تحمل المرحلة؛ Jungle Trail، لعبة منظور شخص أول بتمشي فيها بغابة مولدة عشوائياً؛ Street Slayer، لعبة قتال (beat \'em up) جانبية مصممة لـ DeHub؛ Chartopia، ساحة تداول بتقدر تمشي فيها، مع شاشات بتعرض أسعار السوق لايف على المكاتب ووضع VR من خلال WebXR؛ و God\'s Eye، كرة أرضية 3D لايف بتقدر تختار تحط فيها نسخة تقريبية عن حالك بين مجتمع DeHub. المطورين بيقدروا يبعتوا ألعابهم للمراجعة.',
    arcadeDesc2: 'تنتين منهم مخبيين جوا ثيمات المظهر: حط التطبيق على ثيم "War" وبتوصل لـ Claude of Duty من الثيم نفسه، وثيم "Jungle" بيخبي لعبة Jungle Trail. ألعاب King\'s Gambit و Street Slayer فيها لوحة صدارة (leaderboards)، وكل لعبة إلها "بطاقة مشاركة" خاصة فيها عشان الرابط يفتح بشكل مرتب وين ما نشرته.',
    arcadeLink: 'اقرأ وثائق الألعاب الكاملة',
    settingsTitle: 'الإعدادات',
    settingsB1: 'الملف الشخصي والملفات الشخصية:',
    settingsB7: 'الحسابات والأصول المرتبطة:',
    govLiveDesc: 'التصميم اللي فوق هو الهدف من الحوكمة؛ وصفحة الحوكمة هي المكان اللي بيصير فيه كل شي. الاقتراحات موجودة تحت قسم "الاقتراحات"، المقبولة والمرفوضة، وكل وحدة فيها اسم صاحبها، ونصها، ووضع التصويت عليها. فتح اقتراح جديد بيكلف رسوم 10,000 توكن من DeHub، وبتتأكد على البلوكشين، وكل اقتراح إله صفحته الخاصة مع نقاشات مترابطة. التصويت مجاني: صوتك إله وزن حسب الشارة (badge) اللي معك، والتصويت بيستمر لمدة سبعة أيام، والاقتراح بيمر بأغلبية موزونة مع مشاركة عشر محافظ مختلفة على الأقل، عشان ما يقدر أي شخص لحاله يمرر شي ما حدا شافه.',
    tocDao: 'خزينة الـ DAO',
    daoTitle: 'خزينة الـ DAO',
    daoB2: 'القوة من المساهمة:',
    daoB3: 'الاقتراحات:',
    moreB3Desc: 'إحصائيات الموقع المباشرة — الزوار، مشاهدات الصفحة، وأرقام المجتمع، حسب اليوم أو السنة أو من البداية — منشورة للكل بدل ما تكون داخلية. نفس الصفحة بتعرض إيرادات وتكاليف DeHub، ومبنية من مجموع الإيرادات اليومية والتكاليف اللي سجلها مزودي الخدمة فعلياً، يعني الأمور المالية علنية زيها زي حركة المرور.',
