    intro2: 'لعب و كسب موديل مضمون كمل 100% من رسوم، ما بيحتاجش لحدش من تخفيف أو تضخيم الأسهم ليشجع التفاعل، الدواريات الإيجابية، والنمو العام.',
    intro3: 'يا عايزين نعمل فريق و المجتمع بيشتغلوا بشكل مستقر و متواصل عشان نصل للهدف المشترك، لأن كل ما زادت عدد المستخدمين، زادت الإيرادات، زادت المكافآت، و كل ما زادت المكافآت، زادت عدد المستخدمين اللي بيشتغلوا معانا.',
    chessTitle: 'الشيخ غمبيت',
    chessDesc: 'شطرنج 3D سينمائي مع جيش خلف كل قطعة. ثلاث حضارات مزورة تتقدم وتضرب وتسقط على لوحة مرمرية في أربعة معارك، بثلاثة مستويات قوة محركات، مع سلم تصنيف عبر الإنترنت حسب نظام إلو.',
    dutyTitle: 'كلود من الواجب',
