    jungleTitle: 'جنجل تراييل',
    streetTitle: 'شوارع قاتل',
    streetDesc: 'خَلِّصِ الشَّرِيعَة من المَافِيَة المَشْبُوهَةِ المَانِعَةِ، وِحْصِنِ النَّادِيَ بِكُلِّ السَّعَةِ في هذا اللِّعَبِ المُتَّصِلِ مُنْتَصِبًا، مُنْتَجًا لِدِيهُبِ ومُبْنًى مِن قِبَلِ ستُوديو شُوك بِكْسِل. اِخْتَرِ مِن ثَلَاثَةِ مُقَاتِلِينَ، ثُمَّ ضَرِبْ وَرُجِّ وَأَلْقِ حَتَّى تَنْصَعَ الشَّرِيعَة.',
    trenchTitle: 'شارتوبيا',
    trenchDesc: 'شاشة تجارية بتتجول فيها. عشرات الشاشات بتتعرج حول المكتب بتحمل الإشارات الحية من بينانس، ديكس سكرينر، فيديوهات، تبويبات المتصفح — أي شئ بتحب على الجدار. ممكن تدخلها من خلال هيدست أيضًا.',
    feature1: 'بلا عوائق تلعب وتربح وتكسب',
    releasedIntro: 'شش عايزات بتشغل من داخل ديهوب، في تبويب من المتصفح. مش عايزش تنزيلش ولا تشتريش — خمسها مفتوح المصدر، وواحدة مخصصه لديهوب.',
    godsEyeTitle: 'عيني الله',
    godsEyeDesc: 'كرة الأرض ثلاثية الأبعاد حيوية، مع عرض ذكاء المكاني. لو شئت، يمكن وضع نسخة تقريبية منك بين مجتمع ديهوب',
    submitGames: 'المطورين يمكنهم إرسال ألعابهم الخاصة إلى الملاهي، وكل واحدة يتم مراجعتها قبل أن يتم إدراجها.',
    feature3: 'إرسال محتوى ألعاب عبر تطبيقنا الخاص بالستريمينغ',
    feature4: 'بناء جماعات لامركزية وقسميات رياضية إلكترونية مع لاعبي محترفين موجودين',
    intro1: 'كفريق من اللاعبين والمستريمرين، بنا ونشرنا عدد من الألعاب الترفيهية المجانية في arcade، ونعمل على أول لعبة رئيسية لنا، Last Chad Standing، أول بطولة معركة ملكية لمبارزة MMA، مع فريق من مطوري Ubisoft بالإضافة إلى فريق مؤسس مشارك في نجوم UFC، Oktagon، وPFL، وقد تم تصوير وثائقيات مع أبطال مثل Jorge Masvidal، وتدرب تحت تدريب Conor Mcgregor\'s Coach Kavannah. الوثائقيات أيضًا تم تصويرها بواسطة Luke Barnatt، رئيس غرفة Andrew Tate War room، السابق في UFC، نيابة عن DeHub.',
    intro4: 'إيكوسistema حقيقي ذاتي التحسين والمستدام.',
