    howItWorksDesc2: 'بالتحفظ والتخزين (ستاكينغ) بتتغير طريقة عمل التطبيق بالنسبة لك. ما زادت عدد توكنات ديهاوب اللي بتحتفظ بيها، ما تنخفض رسوم المنصة وما تفتح لك أكثر قدرات: براءات، تفعيل، دفعات ترند، مستويات نادي، وحقوق مزايدة على الشبكة كולה. في الممارسة، العملة ما بتكون إضافي: هي طبقة الإذن، خط المكافآت، ووسيلة الدفع في نفس الوقت.',
