    disclaimerNoApy: 'اِحْذَر: مَاعِنْدَكُ التوكِينات دِيهِ (DeHub) مِشْتَرِكْتِكُ فِى رِشْوِة دِيهِ، وِشْتَرِكْتِكُ فِى رِوْعِة الرِشْوِة دِيهِ، مَاعِنْدَكُ رِتْبَة فِكْسِيَّة (APY) أَوْ رِتْبَة غَايِبَة غَايِبَة أَوْ تِقْوَى فِى رِوْعِة أَيْ شَيْء. كُلّ رِشْوِة تِتْبَعْتِ فِى رِشْوِة الرِشْوِة دِيهِ، وِكُلّ رِوْعِة تِتْبَعْتِ فِى رِوْعِة الرِشْوِة دِيهِ، وِفِى الرِوْعِة دِيهِ دِيهِ فِى فَرْقَة زَمَان مُعَيَّنَة. مِشْتَرِكْتِكُ تِتْبَعْتِ فِى رِوْعِة أَقَلّ مِنْ فَرْقَة زَمَان سَابِقَة، أَوْ مِشْتَرِكْتِكُ زِيرو. مَاعِنْدَكُ شَيْء فِى هَذِهِ الصَّحِيفَة كِتَابَة عَهْد أَوْ تَقْدِير أَوْ عَرْض لِرِوْعِة، وِمِشْتَرِكْتِكُ مَاعِنْدَكُ أَيْ شَيْء فِى هَذِهِ الصَّحِيفَة كِتَابَة عَامِل مَالِى.',
    useAiTitle: 'توليد ذكاء اصطناعي',
