    intro: 'tokens DeHub هي العملة الوظيفية الأصلية لشبكة DeHub؛ DHB هو رمزها. هي الوحدة الواحدة الحسابية عبر كل d\'app — الشيء الذي تستخدمه لتقديم نصيب، فتح المحتوى، كسبه من المشاهدة والإنتاج، واستخدامه في توليد AI. لأنهم يعملون على السلسلة، كل حركة قيمة في الإيكوسستم علنية ومتحقق منها علنًا، وليس في دفتر حسابات خاص يجب أن نؤمن لك به.',
